
// ================================================================ numbers (all from numbers.json)
const cv = N.cv, pool = N.cv_pooled, ncm = N.ncm, nd = N.ncm_detail_H20, h2 = N.h2h, mc = N.h2h_mcnemar, rp = N.rep50, half = N.half, ab = N.ablation;
const DS = ['PHM08', 'FD001', 'FD002', 'FD003', 'FD004'];
const P08 = cv.PHM08['20'];
const ci = o => `${f1(o.ci[0])}–${f1(o.ci[1])}%`;
const ncmRow = (m, H, split = 'cv (primary)') => ncm.summary.find(s => s.method === m && s.H === H && s.split === split);
const NW = ncmRow('warning', 20), NM = ncmRow('mlp_kf', 20), NA = ncmRow('age_only', 20), NWo = ncmRow('warning', 20, 'official');
const hy = ncm.hypotheses;
const halfItems = [half.single.age, half.single.iohmm, half.single.sim, half.single.gbm, half.tcn, half.tcn_gan, half.single.tf_q50, half.single.cnn, half.single.bayes_q50, half.single.lstm, half.hybrid];
const halfMax = Math.max(...halfItems.map(x => x.pct));
const fmtp = p => p < 0.001 ? '< 0.001' : p.toFixed(3);
must(halfItems.length === 11 && halfMax === half.hybrid.pct, 'eleven fixed-time models; the stacked hybrid is the best at half of life');
must(P08.pct === 91.7 && P08.IN === 200 && P08.n === 218, 'PHM08 H=20: 200/218 = 91.7%');
must(pool['20'].IN === 836 && pool['20'].n === 927, 'pooled H=20: 836/927');
must(!hy.W1_in_window_ge_85pct.supported && !hy.W2_late_plus_missed_le_10pct.supported && hy.W3_vs_age_only.supported && !hy.W4_vs_mlp_kf.supported, 'N-CMAPSS: W3 supported, W1 W2 W4 not');
must(NW.IN === nd.IN && NW.n === 99, 'N-CMAPSS primary warning result consistent');
must(DS.every(d => cv[d]['20'].early_limit_active_pct > 90) && cv.PHM08['10'].early_limit_active_pct < 25, 'early limit active for >90% of warnings at H=20 on all development datasets, <25% at H=10 on PHM08');
must(mc['mlp_kf|20'].p_holm7 > 0.05 && mc['mlp_kf|20'].p < 0.05 && mc['mlp_kf|10'].p_holm7 > 0.05 && ['rnn', 'similarity', 'cnn'].every(m => mc[m + '|20'].p_holm7 < 0.001 && mc[m + '|10'].p_holm7 < 0.001), 'head-to-head significance pattern (Holm over seven competitors)');
must(['mlp_kf', 'rnn', 'similarity', 'cnn'].every(m => h2[`ours|20`].pct > h2[`${m}|20`].pct && h2[`ours|10`].pct > h2[`${m}|10`].pct), 'ours has a higher in-window rate than the four challenge-style re-implementations at both levels');
must(rp.reps === 20 && rp.n_ge48 === 3 && rp.n_ge46 === 15, 'repeated splits: 3 of 20 reach 48, 15 of 20 reach 46');
must(N.leakage.passed === 4 && N.leakage.total === 4, 'four leakage checks passed');
const gross = DS.map(d => cv[d]['20'].gross_early); must(gross[4] === 6 && gross.slice(0, 4).reduce((a, b) => a + b, 0) === 1, 'gross early warnings: 6 on FD004, 1 elsewhere');
// ---- revision: battery confirmation, theory, windows, cost, fair deep-learning competitors
const bd = N.battery_detail, BD = N.battery_data, bh = N.battery.hypotheses, bsec = N.battery.secondary_mcnemar;
const BW = bd['cv123|warning|20'], BM = bd['cv123|mlp_kf|20'], BAo = bd['cv123|age_only|20'], BL = bd['lobo|warning|20'], B119 = bd['cv119|warning|20'];
must(BW.IN === 120 && BW.n === 123 && bh.B1_in_window_ge_85pct.supported && bh.B2_late_plus_missed_le_10pct.supported && bh.B3_vs_age_only.supported && bh.B4_vs_mlp_kf.supported, 'battery: 120/123, all four hypotheses supported');
must(BD.cells_used === 123 && BD.kappa === 3 && BD.cells_total === 140, 'battery: 123 of 140 cells, kappa 3');
const TH = N.theory, ths = N.theory_summary; const thr = (d, H) => TH.find(r => r.dataset === d && r.H === H);
must(ths.n_rows === 24 && ths.corr_realised_centred > 0.95, 'theory: 24 dataset-level rows, realised rate tracks the concentration');
const WN = N.windows, CO = N.cost, BC = N.battery_cost;
const WDS = ['PHM08', 'FD001', 'FD002', 'FD003', 'FD004', 'NCMAPSS6'];
must(Object.values(N.windows_repro).every(v => v.every(x => x)) && Object.keys(N.windows_repro).length === 6, 'window re-run reproduces the main [−13, +2] results on all six datasets');
const wp = (d, lo, hi, H = 20) => WN[d][`${lo}|${hi}|${H}`].pct;
const HAVE_DL = N.dl !== undefined;
const GD0 = N.bearing_data;
const HAVE_AB = ab !== undefined;
let abFull, abOr, abRows = [];
if (HAVE_AB) {
  abFull = ab['full|H20']; abOr = ab['oracle_timed|H20'];
  must(abFull.IN === P08.IN && abFull.n === P08.n, 'ablation full model reproduces the main PHM08 H=20 result exactly');
}


// ================================================================ second revision: timing controls and cost-tuned policies (numbers: N.rev2)
const R2 = N.rev2, RDS = ['PHM08', 'FD001', 'FD002', 'FD003', 'FD004', 'NCMAPSS6', 'Battery'];
const RNAME = { PHM08: 'PHM08', FD001: 'FD001', FD002: 'FD002', FD003: 'FD003', FD004: 'FD004', NCMAPSS6: 'N-CMAPSS', Battery: 'Battery' };
const RHOS = [5, 10, 20, 50], LEADS = [0, 5, 10, 15];
must(RDS.every(d => R2.repro[d]), 'revision experiments reproduce the original STW results engine by engine on all seven datasets');
must(RDS.every(d => R2.window[d]['20'].STW.IN === (d === 'NCMAPSS6' ? NW.IN : d === 'Battery' ? BW.IN : cv[d]['20'].IN)), 'revision STW counts equal Tables 2 and 5');
must(LEADS.every(l => RHOS.every(r => Math.abs(R2.cost.PHM08[`${l}|${r}`].STW_window.ratio - CO.PHM08[`${l}|${r}`].stw_rel_pf) < 0.0015)), 'window-tuned STW cost equals the earlier cost analysis on PHM08');
const pw = R2.pooled['20'];
must(pw.const_vs_stw.p > 0.05 && RDS.every(d => R2.window[d]['20'].STW_const.p > 0.05), 'constant estimate not significantly different from STW at H = 20, pooled and on every dataset');
must(RDS.every(d => R2.window[d]['20'].HI_threshold.p < 0.05 && R2.window[d]['20'].HI_threshold.pct < R2.window[d]['20'].STW.pct), 'HI threshold alarm significantly below STW at H = 20 on every dataset');
// regret of each policy against the best of the three alarm policies in each (dataset, lead, rho) cell
const regret = {}; ['STW_window', 'STW_cost', 'HI_cost', 'age'].forEach(m => regret[m] = []);
RDS.forEach(d => LEADS.forEach(l => RHOS.forEach(r => { const c = R2.cost[d][`${l}|${r}`]; const best = Math.min(c.STW_window.ratio, c.STW_cost.ratio, c.HI_cost.ratio);
  Object.keys(regret).forEach(m => regret[m].push(c[m].ratio / best - 1)); })));
const rstat = m => { const v = regret[m].slice().sort((a, b) => a - b); return { mean: 100 * v.reduce((a, b) => a + b, 0) / v.length, med: 100 * v[Math.floor(v.length / 2)], max: 100 * v[v.length - 1], gt10: v.filter(x => x > 0.10).length, n: v.length }; };
const RG = { win: rstat('STW_window'), cost: rstat('STW_cost'), hi: rstat('HI_cost'), age: rstat('age') };
must(RG.win.mean < RG.cost.mean && RG.cost.mean < RG.hi.mean && RG.hi.mean < RG.age.mean, 'mean regret: window-tuned STW < cost-tuned STW < HI < age');
const CS = R2.cost_summary;
must(R2.example.STW_cost.fail > R2.example.STW_window.fail && RHOS.every(r => R2.cost.Battery[`0|${r}`].HI_cost.failures === 0), 'worked cost example and battery HI failures');
must(CS['STW_window|age'].b_sig_better === 0 && CS['STW_window|HI_cost'].b_sig_better <= 4, 'window-tuned STW never significantly costlier than age replacement; at most 4 cells costlier than HI');
const sigCount = (pair, ds, which = 'a') => LEADS.reduce((s, l) => s + RHOS.filter(r => { const b = R2.boot[ds][`${l}|${r}`][pair]; return which === 'a' ? b.hi < 1 : b.lo > 1; }).length, 0);
const ENG5 = ['PHM08', 'FD001', 'FD002', 'FD003', 'FD004'];
const engAge = ENG5.concat(['Battery']).reduce((s, d) => s + sigCount('STW_window|age', d), 0);
must(sigCount('STW_window|age', 'NCMAPSS6') === 0, 'N-CMAPSS: window-tuned STW never significantly cheaper than age replacement');
const hiWorseBatt = sigCount('STW_window|HI_cost', 'Battery', 'b');
const constCells = RDS.flatMap(d => ['10', '15', '20', '30', '40'].filter(H => R2.window[d][H]).map(H => R2.window[d][H].STW_const));
const constSig = constCells.filter(o => o.p < 0.05);
must(constSig.every(o => o.only_other > o.only_stw) && constSig.length === 1 && R2.window.NCMAPSS6['40'].STW_const.p < 0.05, 'constant estimate never significantly worse than STW; significantly better in one combination (N-CMAPSS, H = 40)');
const costBetter = RDS.flatMap(d => LEADS.flatMap(l => RHOS.map(r => R2.boot[d][`${l}|${r}`]['STW_window|STW_cost']))).filter(b => b.lo > 1);
const costBetterPct = 100 * (1 - 1 / (costBetter.reduce((a, b) => a + b.ratio, 0) / costBetter.length));
const winMaxNoNcm = Math.max(...regret.STW_window.filter((x, i) => RDS[Math.floor(i / 16)] !== 'NCMAPSS6')) * 100;

function CTRL_DESIGN() {
  return `Two further baselines were added after the main results were known, to test what the in-window rate measures. (i) A **constant-estimate control** keeps the warning times of our model but replaces its reported estimate by one constant per split, chosen on the training engines' out-of-fold warnings to maximise the number in the window. If the rate depended on the accuracy of the estimate, this control should be clearly worse. (ii) A **health-indicator threshold alarm** has no remaining-life regressor: a linear health indicator, in the spirit of Wang et al. (2008), is fitted by least squares of the exponentially weighted (span 10) baseline-removed sensors of Section 4.2 onto 0 for the first 30 cycles and 1 for the last five cycles of each training engine; the alarm is raised when the smoothed indicator stays at or above a threshold θ for *k* cycles, and the reported estimate is a constant *c* with *H* − 6 ≤ *c* ≤ *H*, the range of estimates our model reports at level *H*. Its smoothing span, debounce, threshold (120 quantiles of the training indicator) and *c* are chosen by the same nested out-of-fold procedure. Both baselines use the same folds, seeds and inner splits as our model, whose results the same runs reproduce engine by engine on all seven datasets.`;
}
function COST_DESIGN() {
  return `(ii) **Maintenance cost**: in a renewal–reward model, an alarm triggers a planned replacement ℓ ∈ {0, 5, 10, 15} cycles later; a unit that is never warned, or whose true remaining life at the alarm is at most ℓ, fails. A planned replacement costs 1 and a failure ρ ∈ {5, 10, 20, 50}; the long-run cost per cycle is the total cost divided by the total cycles of use (Barlow & Hunter, 1960). Four alarm policies are compared, each tuned on the training units' out-of-fold predictions for every (ℓ, ρ): our model tuned to the window, with the warning level *H* ∈ {10, 15, 20, 30, 40} chosen by cost (*window-tuned*); our model tuned directly to the cost, with cap, span, debounce and an alarm threshold τ ∈ {1, …, 60} on the smoothed estimate chosen to minimise the training cost rate (*cost-tuned*); the health-indicator alarm with span, debounce and threshold chosen the same way; and optimal age replacement with the age chosen on training lives. Run-to-failure and perfect foresight (replacement one cycle before failure) bound the range. On the batteries ℓ is in blocks (0–45 cycles) and *H* is chosen like on the engines, unlike in the pre-specified battery protocol. Paired 95% intervals for ratios of cost rates come from 2,000 bootstrap resamples of the test units, with the fitted policies fixed.`;
}
function CTRL_TABLE() {
  const row = d => { const o = R2.window[d]['20']; return [RNAME[d], `${o.STW.IN}/${o.STW.n} (${f1(o.STW.pct)})`, `${o.STW_const.IN} (${f1(o.STW_const.pct)})`, `${o.STW_const.only_stw} / ${o.STW_const.only_other}; ${fmtp(o.STW_const.p)}`,
    `${o.HI_threshold.IN} (${f1(o.HI_threshold.pct)})`, `${o.HI_threshold.only_stw} / ${o.HI_threshold.only_other}; ${fmtp(o.HI_threshold.p)}`, f1(o.HI_threshold.bind_pct)]; };
  const pc = R2.pooled['20'];
  return table('What the in-window rate measures (*H* = 20, five-fold cross-validation). Our model against the same warning times with a constant reported estimate, and against a health-indicator threshold alarm without a remaining-life regressor.',
    ['Dataset', 'Our model: in window (%)', 'Constant estimate: in window (%)', 'Only ours / only constant; *p*', 'Health-indicator alarm: in window (%)', 'Only ours / only health indicator; *p*', 'Health-indicator alarm: early limit can bind (%)'],
    [...RDS.map(row), ['Engines pooled (PHM08, FD001–FD004)', `${pc.STW.IN}/${pc.STW.n} (${f1(pc.STW.pct)})`, `${pc.STW_const.IN} (${f1(pc.STW_const.pct)})`, `${pc.const_vs_stw.only_stw} / ${pc.const_vs_stw.only_const}; ${fmtp(pc.const_vs_stw.p)}`, `${pc.HI_threshold.IN} (${f1(pc.HI_threshold.pct)})`, '–', '–']],
    [1500, 1250, 1250, 1250, 1300, 1300, 1176], 'Exact McNemar tests (discordant units: only ours correct / only the control correct). Battery in blocks of three cycles. All levels *H* = 10–40 are in Supplementary Section S12.');
}
function CTRL_TEXT() {
  const w = R2.window, p = R2.pooled;
  const hiAll = RDS.map(d => w[d]['20'].HI_threshold.pct);
  return [`A warning is correct exactly when the true remaining life at the alarm lies between ŷ − 2 and ŷ + 13 cycles. Because the alarm is raised when the smoothed, shifted estimate first stays below *H*, the reported estimate varies little between units (standard deviation about 2 cycles on PHM08 at *H* = 20, against about 5 cycles for the true remaining life at the alarm), so the rate may depend mainly on *when* the alarm is raised. Table 3 and Supplementary Fig. S3 test this. With the warning times of our model and one constant estimate per split, the in-window rate at *H* = 20 was ${p['20'].STW_const.IN}/${p['20'].STW_const.n} (${f1(p['20'].STW_const.pct)}%) over the five engine datasets, against ${p['20'].STW.IN}/${p['20'].STW.n} (${f1(p['20'].STW.pct)}%) with the model's own estimate (${p['20'].const_vs_stw.only_stw} against ${p['20'].const_vs_stw.only_const} discordant engines, *p* = ${fmtp(p['20'].const_vs_stw.p)}); on PHM08 the two were identical (${w.PHM08['20'].STW.IN} of ${w.PHM08['20'].STW.n}). Over all ${constCells.length} combinations of dataset and level from *H* = 10 to 40, the constant estimate was never significantly worse; in one, N-CMAPSS at the exploratory level *H* = 40, it was significantly better (${R2.window.NCMAPSS6['40'].STW_const.only_other} against ${R2.window.NCMAPSS6['40'].STW_const.only_stw} discordant engines, unadjusted *p* = ${fmtp(R2.window.NCMAPSS6['40'].STW_const.p)}). The in-window rate is therefore a measure of alarm timing: of how often the alarm falls in a band roughly 13 to 28 cycles before failure when *H* = 20, not of how accurate the number attached to it is.`,
    `This does not make the regressor dispensable. The health-indicator threshold alarm, which times its alarm on a classical linear health indicator instead of on the estimated remaining life, placed only ${f1(Math.min(...hiAll))}–${f1(Math.max(...hiAll))}% of first warnings in the window at *H* = 20 (${p['20'].HI_threshold.IN}/${p['20'].HI_threshold.n} = ${f1(p['20'].HI_threshold.pct)}% over the engines), significantly below our model on every dataset, with many alarms too early (${w.PHM08['20'].HI_threshold.early} of ${w.PHM08['20'].HI_threshold.n} on PHM08). What the horizon-focused regressor contributes is a health indicator calibrated in cycles to failure, which lets a single threshold fire at a similar remaining life on units that degrade at different rates. Proposition 1 should be read the same way: the concentration that limits the rate is the concentration of the alarm time relative to failure.`];
}
function COST_TABLE() {
  const rows = [];
  RDS.forEach(d => [0, 10].forEach((l, i) => { const c = r => R2.cost[d][`${l}|${r}`];
    rows.push([i === 0 ? RNAME[d] : '', String(l), ...[10, 50].flatMap(r => ['STW_window', 'STW_cost', 'HI_cost', 'age'].map(m => c(r)[m].ratio.toFixed(2)))]); }));
  return table('Long-run cost rate relative to perfect foresight (1.00 = replacement one cycle before every failure) for alarm policies tuned on training units, at two failure-cost ratios ρ and lead times ℓ of 0 and 10 cycles (blocks for the battery). STW (window): our model tuned to the window, warning level chosen by cost; STW (cost): our model tuned directly to the cost; HI (cost): health-indicator threshold alarm tuned to the cost; Age: optimal age replacement.',
    ['Dataset', 'ℓ', 'ρ = 10: STW (window)', 'STW (cost)', 'HI (cost)', 'Age', 'ρ = 50: STW (window)', 'STW (cost)', 'HI (cost)', 'Age'],
    rows, [1200, 350, 950, 950, 950, 950, 950, 950, 950, 876], `Five-fold cross-validation. All 16 combinations of ℓ ∈ {0, 5, 10, 15} and ρ ∈ {5, 10, 20, 50}, with paired bootstrap intervals, are in Supplementary Section S12. Mean regret over the 112 dataset–ℓ–ρ combinations, relative to the cheapest of the three alarm policies in each: window-tuned STW ${f1(RG.win.mean)}% (median ${f1(RG.win.med)}%, maximum ${f1(RG.win.max)}%), cost-tuned STW ${f1(RG.cost.mean)}% (median ${f1(RG.cost.med)}%, maximum ${f1(RG.cost.max)}%), health-indicator alarm ${f1(RG.hi.mean)}%, age replacement ${f1(RG.age.mean)}%.`);
}
function COST_TEXT2() {
  const c = (d, l, r, m) => R2.cost[d][`${l}|${r}`][m].ratio;
  const p0 = RHOS.map(r => c('PHM08', 0, r, 'STW_window')), a0 = RHOS.map(r => c('PHM08', 0, r, 'age'));
  return [`Table 6 and Fig. 6 price the alarms. The window-tuned model, with its warning level chosen by cost on the training units, brought the long-run cost rate on PHM08 to ${rng(p0)} times that of perfect foresight without lead time, against ${rng(a0)} for optimal age replacement, and it was significantly cheaper than age replacement in ${engAge} of the 96 combinations of lead time and cost ratio on the five engine datasets and the batteries and never significantly more expensive. On N-CMAPSS, where the alarm time was least concentrated (Section 6.8), it was not significantly cheaper than age replacement in any combination. Against the health-indicator alarm tuned directly for cost, it was significantly cheaper in ${CS['STW_window|HI_cost'].a_sig_better} of 112 combinations and significantly more expensive in ${CS['STW_window|HI_cost'].b_sig_better}, ${hiWorseBatt === CS['STW_window|HI_cost'].b_sig_better ? 'all of them' : `${hiWorseBatt} of them`} on the batteries, where a conservative health-indicator threshold avoided every failure at no lead time (${RHOS.map(r => R2.cost.Battery[`0|${r}`].HI_cost.failures).reduce((a, b) => a + b, 0)} failures over the four cost ratios).`,
    `Tuning our model directly for the cost did not improve on tuning it for the window. The cost-tuned policy was significantly cheaper in ${CS['STW_window|STW_cost'].b_sig_better} of 112 combinations, by ${f1(costBetterPct)}% on average, but its losses were larger and harder to predict: up to ${f1(RG.cost.max)}% above the best policy (for example, ${c('PHM08', 10, 50, 'STW_cost').toFixed(2)} against ${c('PHM08', 10, 50, 'STW_window').toFixed(2)} times perfect foresight on PHM08 with ℓ = 10 and ρ = 50), against at most ${f1(winMaxNoNcm)}% for the window-tuned policy outside N-CMAPSS. In that example the cost-tuned alarms came a median of ${R2.example.STW_cost.med_lead} cycles before failure against ${R2.example.STW_window.med_lead} for the window-tuned ones, and ${R2.example.STW_cost.fail} test engines failed against ${R2.example.STW_window.fail}: minimising the empirical cost over a large grid selects alarms that leave little margin on the training units, and with ρ = 50 each additional test failure outweighs many cycles of use. The window, with its narrow late side, builds a margin into the tuning, and only the warning level adapts to the cost. Over all 112 combinations the window-tuned policy had the lowest mean regret (${f1(RG.win.mean)}%, median ${f1(RG.win.med)}%), followed by the cost-tuned policy (${f1(RG.cost.mean)}%), the health-indicator alarm (${f1(RG.hi.mean)}%) and age replacement (${f1(RG.age.mean)}%). In this sense the tolerance window is a robust surrogate for the maintenance cost rather than an arbitrary acceptance rule.`];
}

// ================================================================ front matter
const TITLE = 'Knowing when to warn: Self-timed end-of-life alarms under an asymmetric tolerance window, their maintenance cost, and three pre-specified confirmations';
const ABSTRACT = `Remaining useful life (RUL) models are usually scored at fixed times, yet a replacement decision is taken once. On PHM08 engine data, none of eleven models placed more than ${f1(halfMax)}% of half-life predictions within an asymmetric tolerance window of −13 to +2 cycles. We propose a self-timed warning model: a horizon-focused gradient-boosted regressor with a window-centred, debounced trigger, tuned by nested cross-validation, that raises one scored alarm per unit. At a warning level of 20 cycles, ${f1(P08.pct)}% of PHM08 and ${f1(pool['20'].pct)}% of ${pool['20'].n} simulated engine alarms fell inside the window. Controls show what this measures: a constant estimate at the same alarm times scored ${f1(R2.pooled['20'].STW_const.pct)}%, whereas a health-indicator threshold alarm scored ${f1(R2.pooled['20'].HI_threshold.pct)}%; the regressor's value lies in timing the alarm. In a renewal–reward model, window-tuned alarms were cheaper than optimal age replacement in ${engAge} of 96 lead-time and cost settings on engines and batteries, and had lower mean regret than alarms tuned directly to cost (${f1(RG.win.mean)}% against ${f1(RG.cost.mean)}%). Three pre-specified confirmations (protocols hashed, not registered) delimit the method: ${f1(BW.pct)}% on ${BD.cells_used} lithium-ion cells, ${f1(NW.pct)}% on N-CMAPSS and ${f1(N.bearing_detail['cv|warning|20'].pct)}% on ${N.bearing_data.n} rolling bearings.`;
const nWords = ABSTRACT.split(/\s+/).filter(Boolean).length;
must(nWords <= 200, `abstract ${nWords} words <= 200`);
const HIGHLIGHTS = [
  'A self-timed model raises one end-of-life alarm per unit, scored when raised',
  `At H = 20, ${Math.round(pool['20'].pct)}% of ${pool['20'].n} simulated engine alarms fall within −13 to +2 cycles`,
  'A constant estimate scores the same: the window measures alarm timing',
  'Window-tuned alarms beat age replacement and have the lowest cost regret',
  `Pre-specified tests: ${Math.round(BW.pct)}% on battery cells, ${Math.round(NW.pct)}% on N-CMAPSS, ${Math.round(N.bearing_detail['cv|warning|20'].pct)}% on bearings`];
HIGHLIGHTS.forEach(h => must(h.length <= 85, `highlight <= 85 characters (${h.length})`));
const KEYWORDS = 'Remaining useful life; Predictive maintenance; Early warning; Alarm timing; Renewal–reward model; Turbofan engine; Lithium-ion battery';

const B = [];
B.push(new Paragraph({ children: runs(TITLE, { size: 32, bold: true }), spacing: { after: 240, line: 360 }, alignment: AlignmentType.CENTER }));
B.push(new Paragraph({ children: runs('Anonymised manuscript for review. Author names and affiliations are provided on the separate title page.', { size: 22, italics: true }), alignment: AlignmentType.CENTER, spacing: { after: 240 } }));

B.push(new Paragraph({ children: runs(`**Keywords:** ${KEYWORDS}`, { size: 24 }), spacing: { before: 120, line: 480 } }));

// ================================================================ 1 Introduction
B.push(H1('1. Introduction'));
B.push(P(`Data-driven prognostics estimates the remaining useful life (RUL) of a component from its condition-monitoring history, so that maintenance can be scheduled before failure (Lei et al., 2018; Si et al., 2011). Most studies on turbofan-engine benchmarks report an average error over prediction times chosen by the evaluator: the last observed cycle of truncated test trajectories, all cycles of each trajectory, or fixed fractions of life (Ramasso & Saxena, 2014). A maintenance decision, however, is taken at one moment. What matters to the operator is that the estimate available at that moment is accurate enough to act on, and that it is not late, because a late estimate lets an engine run into failure.`));
B.push(P(`This study started from a concrete requirement of that kind. A remaining-life estimate was to be counted as correct only if its error, predicted minus true cycles left, lay within −13 to +2 cycles: up to 13 cycles early was tolerable, more than 2 cycles late was not. The early limit coincides with the early-prediction constant of the PHM08 challenge score (Saxena et al., 2008); the late limit is much stricter than that score's late constant of 10. We first asked how often existing models meet this requirement when the prediction is made at a fixed point, half of each engine's life. The answer was sobering. Across eleven models, from gradient-boosted trees and recurrent and convolutional networks to a Transformer, a temporal convolutional network with generative data augmentation, a physics-informed Bayesian degradation model and a stacked hybrid of most of them, the best placed ${f1(halfMax)}% of PHM08 predictions inside the window (Section 6.1). At half of life the sensors show almost no wear: the change of a pooled health signal from its early-life level (median ${N.wear_signal.half_life}) is comparable to its cycle-to-cycle noise (${N.wear_signal.noise}), whereas 20 cycles before failure it is ${N.wear_signal.rul20}. Locating the end of life to within 15 cycles from such signals is not realistic.`));
B.push(P(`The requirement becomes attainable if the model is allowed to choose when to speak. In service, an engine is monitored at every cycle, and the decision that needs a precise estimate is the final one: when to remove the engine or to schedule the shop visit. We therefore reformulate the task as a first-warning problem. A policy observes each engine cycle by cycle, stays silent while the engine looks healthy, and issues a single warning with a remaining-life estimate when it judges the end to be near. The warning is scored at the moment it is issued; an engine that fails without a warning counts as late. This is close in spirit to the prognostic horizon of Saxena et al. (2010), the time from which predictions stay within an accuracy band, and to alarm-based maintenance planning (de Pater et al., 2022), but it evaluates one actionable estimate per engine instead of a curve of predictions. Two questions follow, and this paper answers both: what such a score actually measures, and whether tuning for it gives good maintenance decisions. We find that the score measures *when* the alarm is raised far more than the number attached to it, and that alarms tuned for the window are a robust choice when priced by the long-run cost of replacements and failures.`));
B.push(P('The contributions of this paper are as follows.'));
B.push(...LI([
  `(i) A **self-timed warning (STW) model** (Fig. 1): a condition-normalised, causal feature encoder; a gradient-boosted regressor with a capped remaining-life target; and a window-centred, debounced trigger. All four decision settings are chosen by nested cross-validation on training units, so test units never influence the model.`,
  `(ii) **What the score measures.** A constant-estimate control and a health-indicator threshold alarm show that the in-window rate is a property of the alarm time: replacing the model's estimate by a constant did not lower the rate on any of seven datasets, while timing the alarm on a classical health indicator lowered it to about half. A window-centring result (Proposition 1) explains the role of the shift and why the attainable rate is set by how concentrated the alarm time is relative to failure.`,
  `(iii) **A cost evaluation of the alarms.** In a renewal–reward model with lead times and failure costs, window-tuned alarms are compared with alarms tuned directly to the cost, with a cost-tuned health-indicator alarm and with optimal age replacement; the window turns out to be a robust surrogate for the cost.`,
  `(iv) A **leakage-safe first-warning evaluation** on five simulated engine benchmarks (${f1(pool['20'].pct)}% of ${pool['20'].n} first warnings in the window at a warning level of 20 cycles), with an identical-protocol comparison against re-implementations of the three winning PHM08 challenge approaches and deep networks given the same inputs, and a component ablation.`,
  `(v) **Three pre-specified confirmations**, each with the protocol fixed and hashed before the first run: ${f1(BW.pct)}% on measured run-to-failure data of ${BD.cells_used} lithium-ion cells (Severson et al., 2019), with all four hypotheses supported; ${f1(NW.pct)}% on N-CMAPSS (Arias Chao et al., 2021), with three of four unsupported; and ${f1(N.bearing_detail['cv|warning|20'].pct)}% on ${N.bearing_data.n} rolling bearings (Nectoux et al., 2012), with no hypothesis supported. Together they show that the method works on some systems and not on others.`]));
B.push(P('Section 2 reviews related work; Section 3 defines the task; Section 4 describes the model and the window-centring result; Section 5 gives the experimental design; Section 6 reports results; Section 7 discusses them; Section 8 sets out future work on test and maintenance policies and on automatic fault detection and diagnosis; and Section 9 concludes.'));

// ================================================================ 2 Related work
B.push(H1('2. Literature review and contribution'));
B.push(H2('2.1. Remaining useful life prediction for turbofan engines'));
B.push(P(`The C-MAPSS simulations and the PHM08 challenge data (Saxena et al., 2008) are the standard benchmarks for engine prognostics. The three winning PHM08 challenge approaches, published in the conference proceedings, were a similarity-based method that matches the test trajectory against training trajectories (Wang et al., 2008), a recurrent neural network (Heimes, 2008) and an ensemble of neural networks smoothed by a Kalman filter (Peel, 2008). Later work moved to deep sequence models, long short-term memory networks (Zheng et al., 2017) and convolutional networks (Li et al., 2018), usually trained on a remaining-life target capped at about 125 cycles. Ramasso and Saxena (2014) catalogued the evaluation practices on these data and showed how strongly reported scores depend on the choice of test cut-off points and metrics. N-CMAPSS (Arias Chao et al., 2021) adds realistic flight profiles to the simulation. On tabular inputs, tree ensembles remain strong competitors to deep networks (Grinsztajn et al., 2022), which motivated our choice of gradient boosting (Friedman, 2001). Lithium-ion batteries pose the same question in a different physical setting: Severson et al. (2019) cycled commercial cells to failure under fast-charging protocols and predicted their cycle life from the first cycles; their data are one of the few public run-to-failure sets with real measurements and more than a hundred units.`));
B.push(H2('2.2. Evaluation at the time of decision'));
B.push(P(`Saxena et al. (2010) proposed metrics that follow a prediction over time, among them the prognostic horizon and α–λ accuracy, where the tolerated error shrinks as failure approaches. Asymmetric losses that penalise late predictions more than early ones are common (Rengasamy et al., 2020), and the PHM08 score itself is asymmetric. Maintenance-oriented studies link prognostics to decisions: alarm-based scheduling for aircraft engines (de Pater et al., 2022), dynamic maintenance frameworks driven by predicted failure probabilities (Nguyen & Medjaher, 2019; Mitici et al., 2023), reinforcement learning on probabilistic prognostics (Lee & Mitici, 2023) and decision-based metrics for prognostic algorithms (Kamariotis et al., 2024). Degradation-signal models with Bayesian updating (Gebraeel et al., 2005) produce a residual-life distribution that can be acted on when needed. The classical reference for any condition-based policy is age replacement, which uses no condition information and replaces a unit at the age that minimises the long-run cost rate (Barlow & Hunter, 1960); we use it as the baseline of our cost analysis. Our contribution sits between these lines: we keep a standard regression model but let a tuned decision rule choose the single moment at which its estimate is issued and judged. Unlike alarm-based scheduling, which acts when a probabilistic RUL estimate crosses a threshold (de Pater et al., 2022), and decision-oriented metrics, which score a prognostic algorithm by the cost of the decisions it induces (Kamariotis et al., 2024), we ask what a tolerance-window score rewards, show that it rewards the alarm time rather than the estimate, and measure how well window-tuned alarms perform when priced by cost.`));
B.push(H2('2.3. Leakage and model selection'));
B.push(P(`Model selection on the data used for evaluation biases error estimates (Varma & Simon, 2006), and leakage between training and test data is a leading cause of irreproducible results in machine-learning-based science (Kapoor & Narayanan, 2023). Run-to-failure benchmarks invite two specific leaks: splitting by rows rather than by engines, and evaluating at a cut point derived from the engine's total life, which the model could exploit. Our design avoids both, and Section 5.5 describes the checks. Pre-specifying an analysis and fixing it before the data are seen is the standard remedy against selective reporting in confirmatory studies (Nosek et al., 2018); we apply it to three confirmation datasets.`));

// ================================================================ 3 Problem
B.push(H1('3. Problem formulation'));
B.push(P(`An engine *i* is observed at flight cycles *t* = 1, …, *L*_{i}, where *L*_{i} is its (unknown) life. At cycle *t* the true remaining life is *r*_{t} = *L*_{i} − *t*. A warning policy maps the history observed up to *t* to either *silent* or *warn*, together with an estimate ŷ_{t}. The first-warning time is`));
B.push(EQ('*t*^{*} = min { *t* < *L*_{i} : the policy warns at *t* },'));
B.push(P(`and the error of the warning is *e* = ŷ_{t*} − *r*_{t*}. A warning is **correct** if −13 ≤ *e* ≤ +2, **too early** if *e* < −13 and **too late** if *e* > +2. An engine that reaches failure without a warning is **missed** and counted with the late outcomes, since it is the most dangerous case. The primary metric is the share of engines whose first warning is correct (the in-window rate). We also report the late-or-missed and early rates, the lead time *r*_{t*}, and the share of warnings for which the early limit can bind at all. A warning issued with fewer than 13 cycles left can be too early only if its estimate is negative, which practically never happens. If a policy warned only in the last few cycles, the early limit would be inactive and the task much easier. We therefore report, for every setting, the share of warnings issued with at least 13 cycles left. We write "engine" for the monitored unit; on the battery and bearing data a unit is a cell or a bearing, and a cycle of the model is a block of consecutive charge–discharge cycles or vibration snapshots (Section 5.4).`));
B.push(P(`The warning level *H* expresses when the operator wants to be warned: the policy warns when it believes that about *H* cycles are left. Small *H* gives accurate but short-notice warnings; large *H* gives more notice but less precision. We report *H* ∈ {10, 15, 20} on all datasets and also *H* = 30 and 40 on PHM08 (and on all engine datasets in the secondary analyses of Section 5.6). *H* = 20 is the primary level because it is the smallest of these at which the early limit can bind for more than 90% of PHM08 warnings (Sections 5.2 and 6.3).`));
B.push(P(`Two remarks frame the evaluation. First, a warning is correct exactly when the true remaining life at the alarm lies between ŷ_{t*} − 2 and ŷ_{t*} + 13. The window therefore scores the alarm time and the estimate jointly, and Section 6.3 shows that, for our model, the alarm time carries almost all of the information. Second, the window is an operational acceptance criterion, not a cost. We therefore also price every alarm policy in a renewal–reward model with replacement lead times and failure costs (Sections 5.6 and 6.6).`));

// ================================================================ 4 Model
B.push(H1('4. The self-timed warning model'));
B.push(P(`Fig. 1 shows the architecture. The online part runs at every cycle of an engine in service; the offline part fixes its settings using training engines only.`));
B.push(...figure(__dirname + '/img/Fig1_STW_architecture.png', 'Architecture of the self-timed warning (STW) model. Online (top): regime-normalised sensors are encoded causally and mapped to an estimate ŷ_{t}, which is smoothed and shifted to ỹ_{t}; a warning is issued the first time ỹ stays at or below *H* for *k* cycles. Offline (bottom): θ = (*c*, *m*, *k*, *s*) is chosen on inner out-of-fold predictions of the training engines and frozen; test engines are scored once. Inset: the scoring window for *e* = ỹ_{t*} − *r*_{t*}.'));
B.push(H2('4.1. Condition normalisation'));
B.push(P(`Engine sensor readings depend strongly on the operating condition (altitude, Mach number, throttle). Each sensor *j* is z-scored within its operating regime *a*, with means and standard deviations estimated from training engines only:`));
B.push(EQ('*z*_{t,j} = ( *x*_{t,j} − μ_{j}(*a*_{t}) ) / σ_{j}(*a*_{t}).'));
B.push(P(`PHM08, FD002 and FD004 have six regimes, FD001 and FD003 one, and N-CMAPSS uses the three flight classes. A sensor is dropped if it is constant within any regime, which leaves ${N.sensors_kept.PHM08} sensors on PHM08, FD001 and FD002 and ${N.sensors_kept.FD003} on FD003 and FD004. On N-CMAPSS we used, as in the pre-specified protocol, the six temperature and shaft-speed channels T24, T30, T48, T50, Nf and Nc; an exploratory re-run with all 14 channels is reported in Section 6.7. On the battery data, the seven per-cycle quantities (discharge and charge capacity, internal resistance, average, minimum and maximum temperature, and charge time) are z-scored as one regime, as fixed in the protocol. The protocol justified this by stating that all cells share the same test conditions apart from the charging protocol; in fact the three batches also differ in the rest periods of the cycling schedule (Severson et al., 2019). The model is given neither.`));
B.push(H2('4.2. Causal feature encoder'));
B.push(P(`At cycle *t* the encoder uses only cycles 1, …, *t*. It computes an early-life baseline **b**_{t}, the mean of the first min(20, *t*) cycles, which captures manufacturing variation and initial wear; exponentially weighted means with spans 10 and 30 of the baseline-removed signals **z** − **b**; least-squares slopes over the last 15 and 40 cycles (smoothed with span 5), which capture the rate of degradation; and the age *t*. This gives 5*p* + 1 features for *p* sensors. Section 5.5 verifies causality: deleting all data after cycle *t* does not change the prediction at *t*.`));
B.push(H2('4.3. Horizon-focused regressor'));
B.push(P(`A histogram gradient-boosted regressor (Pedregosa et al., 2011) with absolute-error loss is trained on all cycles of the training engines with the target`));
B.push(EQ('*y*_{t} = min( *r*_{t}, *c* ),   *c* ∈ {40, 60, 90}.'));
B.push(P(`The conventional piecewise-linear target caps remaining life at about 125 cycles because early degradation is unobservable (Heimes, 2008). We allow lower caps, so that above *c* the model only has to say "far from failure" and its loss is spent on the last *c* cycles, where the warning is issued; a cap also flattens the prediction during the healthy phase. The cap is chosen per split by the inner cross-validation (Section 4.5). The ablation in Section 6.5 shows that having a cap matters, whereas its exact value matters little: the conventional cap of 125 performed almost as well as the selected caps of 40 or 60.`));
B.push(H2('4.4. Window-centred, debounced trigger'));
B.push(P('The raw estimate is smoothed causally and shifted:'));
B.push(EQ('ỹ_{t} = EWM_{m}(ŷ)_{t} + *s*,'));
B.push(P(`where EWM_{m} is an exponentially weighted mean with span *m* ∈ {1, 3, 6} (*m* = 1 means no smoothing) and *s* ∈ [−12, +8] in steps of 0.5. The shift centres the estimates in the tolerance window: the window [−13, +2] is centred at −5.5, and a negative shift trades the narrow late side against the wide early side (Section 4.6 makes this precise). A warning is issued at the first cycle at which ỹ has been at or below *H* for *k* ∈ {1, 2, 3, 5} consecutive cycles:`));
B.push(EQ('*t*^{*} = min { *t* : ỹ_{τ} ≤ *H* for all τ = *t* − *k* + 1, …, *t* },'));
B.push(P(`and the reported estimate is ỹ_{t*}. The debounce *k* is meant to suppress warnings triggered by a single noisy cycle; the ablation shows that its effect, like that of the smoothing, is small.`));
B.push(H2('4.5. Nested selection of the decision settings'));
B.push(P(`The settings θ = (*c*, *m*, *k*, *s*) are chosen on training engines only. The training engines of an outer split are divided into five inner folds (seed 100 + outer fold). For each inner fold and each cap, the regressor is fitted on the other inner folds, which also supply the normalisation statistics, and predicts every cycle of the held-out inner engines. This gives out-of-fold predictions for all training engines. For each warning level *H*, the grid (the caps with *c* ≥ *H* + 20 × 3 spans × 4 debounces × 41 shifts) is searched for the setting that maximises the number of training engines whose first warning is correct; ties are broken towards smaller |*s*|. The regressor is then refitted on all training engines with the selected cap, θ is frozen, and each test engine is processed once. The search is vectorised over *s*. Supplementary Table S8 lists all settings, and Supplementary Section S14 lists the scripts that produce every number.`));
B.push(H2('4.6. Why a shift, and what limits the in-window rate'));
B.push(P(`A simple model explains the role of the shift and gives a benchmark for the attainable rate. Let ε = EWM_{m}(ŷ)_{t*} − *r*_{t*} be the error of the unshifted (smoothed) estimate at the moment of the first warning, so that the scored error is *e* = ε + *s*, and write the window as [*a*, *b*] = [−13, +2] with width *w* = *b* − *a* = 15.`));
B.push(P(`**Proposition 1.** Suppose that, over the range of shifts considered, ε has a continuous distribution *F* that does not depend on *s* (assumption A1). Then the probability of a correct first warning is`));
B.push(EQ('*P*(*s*) = *F*(*b* − *s*) − *F*(*a* − *s*).'));
B.push(P(`(i) For every *s*, *P*(*s*) ≤ *C*_{w}(*F*) = sup_{x} [*F*(*x* + *w*) − *F*(*x*)], the largest probability that ε falls in some interval of width *w* (the *concentration* of the error). (ii) If *F* has a density that is unimodal and symmetric about its median *m*, *P*(*s*) is maximised at`));
B.push(EQ('*s*^{*} = (*a* + *b*)/2 − *m* = −5.5 − *m*,'));
B.push(P(`and the maximum is *C*_{w}(*F*) = Pr(|ε − *m*| ≤ *w*/2) = Pr(|ε − *m*| ≤ 7.5). The proof is given in Supplementary Section S2.`));
B.push(P(`Two consequences guide the design and the interpretation. First, an unbiased estimator (*m* ≈ 0) should be shifted by about −5.5 cycles: without the shift every error above +2 cycles is late, a large part of the upper half of the error distribution, while most of the wide early side goes unused. This is why removing the shift is the most damaging single-component ablation (Section 6.5). Second, once the shift is right, the in-window rate is governed by the concentration of the error *at the warning*, not by the average error over life. This is what the horizon-focused target is for: capping the target at *c* spends the regressor's capacity on the last *c* cycles and tightens ε near *H*. Assumption A1 is an approximation, because changing *s* moves the warning to a slightly different cycle; Section 6.8 checks the Proposition against all datasets, and Supplementary Section S2 gives the proof.`));

// ================================================================ 5 Experimental design
B.push(H1('5. Experimental design'));
B.push(H2('5.1. Data'));
B.push(...table('Datasets. Life = number of cycles to failure of the run-to-failure units.', ['Dataset', 'Units', 'Rows', 'Life (min–max; median)', 'Regimes', 'Role'],
  [...DS.map(d => [d, N.data[d].engines, N.data[d].rows.toLocaleString('en-US'), `${N.data[d].life_min}–${N.data[d].life_max}; ${N.data[d].life_median}`, N.data[d].regimes, d === 'PHM08' ? 'development' : 'additional evaluation']),
   ['N-CMAPSS', N.data['N-CMAPSS'].engines, N.data['N-CMAPSS'].rows.toLocaleString('en-US'), `${N.data['N-CMAPSS'].life_min}–${N.data['N-CMAPSS'].life_max}; ${N.data['N-CMAPSS'].life_median}`, `${N.data['N-CMAPSS'].regimes} (flight class)`, 'pre-specified confirmation 1 (simulation)'],
   ['Battery (Severson et al., 2019)', `${BD.cells_used} cells`, N.battery_rows.toLocaleString('en-US'), `${BD.life_min}–${BD.life_max}; ${BD.life_median}`, '1', 'pre-specified confirmation 2 (laboratory measurements)'],
   ['Bearings (Nectoux et al., 2012)', `${GD0.n} bearings`, N.bearing_rows.toLocaleString('en-US'), `${GD0.life_min}–${GD0.life_max}; ${GD0.life_median}`, '3 (load/speed)', 'pre-specified confirmation 3 (laboratory measurements)']],
  [1500, 950, 1000, 1900, 1200, 2476], `N-CMAPSS: one row per engine and flight cycle (means of the 1 Hz signals), nine subsets; 60 development and 39 test engines in the official split. Battery: one row per cell and charge–discharge cycle; life = official cycle life (first cycle below 80% of the nominal 1.1 Ah capacity); ${BD.cells_used} of the ${BD.cells_total} cell records (135 physical cells, because five records continue five others) after the exclusions of Supplementary Section S5. Bearings: one row per vibration snapshot (0.1 s every 10 s); life = number of snapshots to failure.`));
B.push(P(`We use the 218 run-to-failure training engines of PHM08 and the training sets of C-MAPSS FD001–FD004 (Saxena et al., 2008). The truncated official test sets are not used, because the first-warning task needs complete trajectories. For N-CMAPSS (Arias Chao et al., 2021), the 1 Hz flight data were reduced to one row per engine and flight cycle (the mean of each signal over the flight). All 99 engines of the nine subsets present in the archive we used (DS08d was absent) were used. The battery data are laboratory measurements of commercial lithium iron phosphate/graphite cells (A123 APR18650M1A, 1.1 Ah) cycled to failure under fast-charging protocols in three batches (Severson et al., 2019; ${BD.policies} distinct protocols among the cells used); we used the per-cycle summary of each cell. The bearing data are the 17 complete run-to-failure records of the PRONOSTIA platform (Nectoux et al., 2012), with horizontal and vertical acceleration sampled at 25.6 kHz in 0.1-s snapshots every 10 s.`));
B.push(H2('5.2. Development history and splits'));
B.push(P(`The model was developed on PHM08 after the fixed-time results of the age-only, gradient-boosted, recurrent, convolutional, hidden-Markov and similarity models were known; the other fixed-time reference models of Section 6.1 (Transformer, Bayesian, temporal convolutional and stacked models) were run afterwards, in an attempt to improve fixed-time prediction. The warning levels and grids were fixed on PHM08, and C-MAPSS FD001–FD004 were then run once with unchanged code; we call them additional evaluation datasets, although they were not pre-specified. The primary level *H* = 20 was designated after these runs, by the criterion of Section 3 computed on PHM08 (the early limit could bind for ${f1(P08.early_limit_active_pct)}% of warnings at *H* = 20 and ${f1(cv.PHM08['15'].early_limit_active_pct)}% at *H* = 15); the C-MAPSS results were known at that time. The protocol for N-CMAPSS, including four hypotheses, was written and hashed (SHA-256 ${N.ncm_protocol.sha256.slice(0, 16)}…, ${N.ncm_protocol.written}) before the model or any competitor was run on those data (Section 5.4). N-CMAPSS had been used earlier in this project for a different question: fixed-time predictions of gradient-boosted, recurrent, convolutional, hidden-Markov and age-only models were known when the thresholds of the hypotheses were set, but no warning rule had ever been fitted or evaluated on it. The battery protocol (SHA-256 ${BD.protocol_sha256.slice(0, 16)}…) and the bearing protocol (${GD0.protocol_sha256.slice(0, 16)}…) were written after the previous confirmation results were known and copy the model, the grids, the window and the four criteria unchanged (Section 5.4).`));
B.push(P(`All evaluations split by engine. The main results use five-fold outer cross-validation (seed 2026); every engine is a test engine exactly once. Settings are selected with the inner cross-validation of Section 4.5.`));
B.push(H2('5.3. Competitors under an identical protocol'));
B.push(P(`The PHM08 challenge leaderboard used withheld test answers and a different task, so it cannot be compared directly. Instead we re-implemented the three winning challenge approaches and a convolutional baseline and ran them through exactly the same first-warning rule:`));
B.push(...LI([
  '• similarity-based prediction in the spirit of Wang et al. (2008): the median of a remaining-life distribution obtained by matching the recent principal-component trajectory against all training trajectories;',
  '• a recurrent network in the spirit of Heimes (2008): a two-layer LSTM (Zheng et al., 2017) on 30-cycle windows of the seven temperature and shaft-speed sensors (s2, s3, s4, s8, s9, s13, s14), target capped at 125 cycles;',
  '• a multilayer perceptron with a Kalman filter over time in the spirit of Peel (2008): a single network (not an ensemble) with 64 and 32 hidden units on our causal features of the 15 sensors, target capped at 125, followed by a scalar Kalman filter in which the estimate decreases by one cycle per cycle, with the process-to-measurement noise ratio chosen with the other settings;',
  '• a convolutional network following Li et al. (2018), on the same 30-cycle windows of seven sensors as the LSTM.']));
B.push(P(`In this comparison every method, including ours, was fitted on the 75% fit engines of each outer training part (seed 7) and had its warning settings (*m*, *k*, *s* and its own option) chosen on the remaining 25% calibration engines, with a shift grid of −15 to +10. Our model therefore scores slightly lower here than in the main nested protocol, which uses all training engines. The methods are re-implementations in the spirit of the published approaches, not the original code, and they differ in their inputs: the LSTM and CNN see seven sensors, the MLP sees our encoder of 15 sensors.`));
B.push(P(`To separate the architecture from the inputs and the target, three deep networks were also run with exactly what our model receives: the 15 regime-normalised sensors and the age, and a target cap chosen from {40, 60, 90} together with the other warning settings. They are the LSTM and the CNN above on 30-cycle windows of these inputs, and a hybrid Transformer with two self-attention blocks over the last 40 cycles of the sensors and regime indicators, concatenated with our causal features and trained with a quantile (pinball) loss, of which the median is used. All other steps of the protocol are unchanged.`));
B.push(P(CTRL_DESIGN()));
B.push(H2('5.4. Three pre-specified confirmations'));
const FG = N.bearing_detail['cv|warning|20'], FM = N.bearing_detail['cv|mlp_kf|20'], FA = N.bearing_detail['cv|age_only|20'], fh = N.bearing.hypotheses, GD = N.bearing_data;
must(FG.IN === 0 && FG.n === 17 && !fh.F1_in_window_ge_85pct.supported && !fh.F2_late_plus_missed_le_10pct.supported && !fh.F3_vs_age_only.supported && !fh.F4_vs_mlp_kf.supported, 'bearings: 0/17, no hypothesis supported');
B.push(P(`Three datasets were analysed only after a protocol had been written and hashed (SHA-256 of the protocol text): N-CMAPSS (${N.ncm_protocol.written}), the battery data (${BD.protocol_written}, before the data had been obtained for this project) and rolling bearings (${GD.protocol_written}, before any bearing measurement had been read; the protocol was also shared outside the analysis environment, in a time-stamped message, before the download). Each protocol fixed the data, any time scale, the model and its grids (unchanged), two competitors under the same tuning (an age-only regressor with the cycle count as its only input, and the MLP with Kalman filter of Section 5.3), the splits (primary: five-fold cross-validation by unit, seed 2026), the warning levels (primary *H* = 20) and the same four hypotheses at *H* = 20: in-window rate ≥ 85%; late-or-missed rate ≤ 10%; higher in-window rate than age-only; and higher in-window rate than the MLP with Kalman filter (both by the exact McNemar test, two-sided *p* < 0.05). The protocols were written in sequence, each after the previous result was known, but the model was not changed in response to any of them. The hashes were kept by the authors and not deposited with a registry, so the times are attested by the authors and by file time stamps only; a hash shows that a protocol has not changed since it was hashed, not when it was hashed. Recorded deviations are listed in the protocol files and in Supplementary Sections S5–S7.`));
B.push(P(`**N-CMAPSS** (99 simulated engines) uses six temperature and shaft-speed channels and the three flight classes as regimes. **Battery** (${BD.cells_used} commercial LFP/graphite cells; Severson et al., 2019) uses the seven per-cycle quantities of Section 4.1 as one regime. Battery lives (median ${BD.life_median} cycles) are about ${Math.round(BD.life_median / 209.5 * 10) / 10} times longer than PHM08 engine lives, so the protocol rescales time instead of re-tuning: consecutive cycles are averaged in blocks of κ = max(1, round(median life / 209.5)) = ${BD.kappa}, and the model, warning level and window are applied in blocks (in cycles the window is [−39, +6] and *H* = 20 is 60 cycles). Ten split-test records and five cells that never reach end of life were excluded before any model was run (Supplementary Section S5). **Bearings** are the ${GD.n} ball bearings run to failure on the PRONOSTIA platform for the IEEE PHM 2012 challenge (Nectoux et al., 2012) under three load and speed conditions, which serve as regimes. Each 0.1-s vibration snapshot, recorded every 10 s, is reduced to eight features (root mean square, peak, kurtosis and crest factor of the horizontal and vertical acceleration), and the same time-scale rule gives blocks of κ = ${GD.kappa} snapshots (70 s). The bearing protocol also fixed, before it was run anywhere, a theory-guided shift rule (STW-T) that is described in Section 5.6.`));
B.push(H2('5.5. Leakage checks and statistics'));
B.push(P(`Four checks were run on PHM08: disjoint outer and inner engine sets (E1); causality, by recomputing predictions from truncated histories (E2); a negative control trained on labels built from permuted lives (E3); and exact reproduction of a refitted fold (E4) (Supplementary Section S4). The decision rule never uses the engine's total life, and the evaluation point is chosen by the model itself, so the leak inherent in evaluating at a cut point derived from the total life cannot arise. Proportions carry Clopper–Pearson 95% intervals (Clopper & Pearson, 1934). Paired comparisons use the exact McNemar test (McNemar, 1947), with Holm's correction over the seven competitors at each level of Table 4 and over the nine ablation variants of Table 5 (Holm, 1979); the hypothesis tests of the confirmations are unadjusted, as pre-specified.`));
B.push(H2('5.6. Secondary analyses'));
B.push(P(`For the fixed-time reference analysis of Section 6.1, eleven models were evaluated at fixed fractions of each test engine's life in the same outer folds (Supplementary Section S1); the single models are scored on their raw estimates, without a window-centring shift, so their rates understate what a shift could add, whereas the stacked hybrid includes a tuned shift. Following the evaluation practice of the group that set the tolerance window, we also drew 50 random test engines and 168 training engines thirty times on PHM08 (seeds 1001–1030; inner-split seeds 2001–2030), with the same nested selection inside the 168 engines.`));
B.push(P(`Three further analyses were added after the main results were known. (i) **Other windows** [−10, +2], [−20, +5] and [−30, +10], with the settings re-selected for each window by the same nested procedure (Supplementary Section S8). ${COST_DESIGN()} (iii) **Theory-guided shift (STW-T)**: following Proposition 1, the shift is chosen so that the median out-of-fold warning error equals the window centre, −5.5; it was pre-specified in the bearing protocol and is descriptive on the other datasets (Supplementary Section S10). The thirty random 50-engine test sets are reported in Supplementary Section S11.`));

